// Procesa la transcripción y devuelve el texto + el contexto para el agente
const raw = $input.first().json;

// La respuesta puede estar en distintas ubicaciones según la versión
let transcripcion = '';
if (raw.content?.parts?.[0]?.text) {
  transcripcion = raw.content.parts[0].text;
} else if (raw.response?.text) {
  transcripcion = raw.response.text;
} else if (raw.text) {
  transcripcion = raw.text;
} else if (typeof raw === 'string') {
  transcripcion = raw;
}

transcripcion = (transcripcion || '').trim();

// Casos donde el audio no aporta nada útil
if (!transcripcion || transcripcion === '[AUDIO_INAUDIBLE]' || transcripcion === '[SIN_VOZ]') {
  return {
    json: {
      ok: false,
      transcripcion: '',
      contexto_audio: '[AUDIO RECIBIDO PERO INAUDIBLE] Pide al cliente que repita por escrito o con un audio más claro.',
      mensaje_inyectar: 'No se pudo entender el audio'
    }
  };
}

// OK: hay transcripción válida
return {
  json: {
    ok: true,
    transcripcion,
    contexto_audio: `[MENSAJE RECIBIDO POR AUDIO] El cliente envió un nota de voz que fue transcrita. Procesa el contenido como si lo hubiera escrito, pero ten en cuenta que viene de audio (puede tener errores de transcripción menores o tono coloquial).`,
    mensaje_inyectar: transcripcion
  }
};
